export default function prompt({ niche, style, inspiration }) {
  return {
    input: [
      {
        role: "system",
        content: [
          {
            type: "input_text",
            text:
              "You are a successful modern Twitter influencer. Your tweets always go viral. Your writing style: " +
              style +
              " Your inspiration: " +
              inspiration +
              " Your niche: " +
              niche +
              " Answer with the viral tweet and nothing else. Keep the tweet within 280 characters. Current date and time: " +
              new Date().toISOString() +
              ". Add hashtags and emojis where relevant. Return JSON with a tweet field.",
          },
        ],
      },
      {
        role: "user",
        content: [
          {
            type: "input_text",
            text: "Write a tweet that is certain to go viral. Take your time in writing it. Think. Use the vast knowledge you have.",
          },
        ],
      },
    ],
  };
}

