export default function result({ response }) {
  if (response?.status !== "completed" || !Array.isArray(response.output))
    throw Error("OpenAI response incomplete");
  const text = response.output
    .flatMap((x) => x.content ?? [])
    .filter((x) => x.type === "output_text")
    .map((x) => x.text)
    .join("");
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw Error("OpenAI did not return JSON");
  }
  if (typeof parsed.tweet !== "string" || !parsed.tweet.trim())
    throw Error("OpenAI did not return a tweet");
  return { tweet: parsed.tweet, tooLong: parsed.tweet.length > 280 };
}
